import { Inject, Injectable, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';

interface ScriptOptions {
	module?: boolean;
	defer?: boolean;
	async?: boolean;
}

@Injectable({ providedIn: 'root' })
export class LazyLoaderService {
	constructor(
		@Inject(PLATFORM_ID) private platformId: object,
		@Inject(DOCUMENT) private document: Document,
	) {}

	loadScript(src: string, options: ScriptOptions = {}): Promise<void> {
		return new Promise((resolve, reject) => {
			if (!isPlatformBrowser(this.platformId) || !this.document?.body) {
				resolve();
				return;
			}

			const existingScript = this.document.querySelector(`script[src="${src}"]`);
			if (existingScript) return resolve();

			const script = this.document.createElement('script');
			script.src = src;
			script.type = options.module === false ? 'text/javascript' : 'module';
			script.defer = Boolean(options.defer);
			script.async = Boolean(options.async);
			script.onload = () => resolve();
			script.onerror = () => reject();
			this.document.body.appendChild(script);
		});
	}
}
