import {
	Component,
	OnInit,
	OnDestroy,
	Renderer2,
	Inject,
	PLATFORM_ID,
} from '@angular/core';
import { DOCUMENT, isPlatformBrowser, Location } from '@angular/common';
import { Meta } from '@angular/platform-browser';

@Component({
	selector: 'app-root',
	templateUrl: './app.component.html',
	styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit, OnDestroy {
	private scrollListener: () => void;
	private splineInterval: any;
	private readonly isBrowser: boolean;

	constructor(
		private renderer: Renderer2,
		public location: Location,
		private metaTagService: Meta,
		@Inject(PLATFORM_ID) platformId: object,
		@Inject(DOCUMENT) private document: Document,
	) {
		this.isBrowser = isPlatformBrowser(platformId);
	}

	ngOnInit(): void {
		this.setMetaTags();
		if (this.isBrowser) {
			void this.initBrowserOnlyFeatures();
		}
	}



	ngOnDestroy(): void {
		if (this.scrollListener) {
			this.scrollListener();
		}
		if (this.splineInterval) {
			clearInterval(this.splineInterval);
		}
	}

	private async initBrowserOnlyFeatures(): Promise<void> {
		const AOS = await import('aos');

		AOS.init();
		this.scrollToTop();
		this.bindScrollEffect();
		this.hideSplineLogo();

		const inactiveBtn = this.document.getElementById('inactive');
		if (inactiveBtn) {
			inactiveBtn.addEventListener('click', () => {
				inactiveBtn.classList.remove('active');
				inactiveBtn.classList.add('active');
			});
		}
	}

	private bindScrollEffect(): void {
		if (!this.isBrowser) {
			return;
		}

		this.scrollListener = this.renderer.listen('window', 'scroll', () => {
			const navbar = this.document.querySelector('.navbar-transparent');
			if (window.scrollY > 50) {
				navbar?.classList.add('active');
			} else {
				navbar?.classList.remove('active');
			}
		});
	}

	private scrollToTop(): void {
		if (!this.isBrowser) {
			return;
		}

		window.scroll({
			top: 0,
			left: 0,
			behavior: 'smooth'
		});
	}

	private setMetaTags(): void {
		this.metaTagService.addTags([
			{ name: 'keywords', content: 'pixtar' },
			{ name: 'robots', content: 'index, follow' },
			{ name: 'author', content: 'Ipcs' },
			{ name: 'viewport', content: 'width=device-width, initial-scale=1' },
			{ name: 'date', content: '2022-10-1', scheme: 'YYYY-MM-DD' },
			{ charset: 'UTF-8' }
		]);
	}

	private hideSplineLogo(): void {
		if (!this.isBrowser) {
			return;
		}

		this.splineInterval = setInterval(() => {
			const splineViewer = this.document.querySelector('spline-viewer');
			const shadowRoot = (splineViewer as any)?.shadowRoot;
			const logo = shadowRoot?.querySelector('#logo');
			if (logo) {
				logo.setAttribute('aria-label', 'Spline logo');
				(logo as HTMLElement).style.display = 'none';
				clearInterval(this.splineInterval);
			}
		}, 1000);
	}

	removeFooter(): boolean {
		const path = this.location.prepareExternalUrl(this.location.path()).slice(1);
		const noFooterRoutes = ['/signup', '/nucleoicons', 'p/kbn', 'p/kbn2', 'p/js', 'p/io', 'p/godly'];
		return !noFooterRoutes.some(route => path.includes(route));
	}

	removeHeader(): boolean {
		const path = this.location.prepareExternalUrl(this.location.path()).slice(1);
		const noHeaderRoutes = ['p/kbn', 'p/kbn2', 'p/js', 'p/io', 'p/godly'];
		const hideHeader = noHeaderRoutes.includes(path);
		if (!this.isBrowser) {
			return !hideHeader;
		}

		const botPenguinLauncher = this.document.getElementById('botpenguin-launcher-12');

		if (hideHeader && botPenguinLauncher?.classList.contains('botpenguin-right')) {
			const botChat = this.document.querySelector('.BotPenguin-chat');
			if (botChat) {
				botChat.classList.add('d-none');
			}
		}

		return !hideHeader;
	}
}
