import { Component, OnInit } from '@angular/core';
import { Meta, Title } from '@angular/platform-browser';
import { environment } from '../../environments/environment';
import { PageService } from '../providers/page/page.service';
@Component({
  selector: 'app-process',
  templateUrl: './process.component.html',
  styleUrls: ['./process.component.scss']
})
export class ProcessComponent implements OnInit {
  baseUrl:any;
  constructor(private pageservice:PageService,private metaTagService: Meta,
    private titleService: Title,  ) {
    this.get_PageMeta();
    this.baseUrl = environment.baseUrl + '/assets';
  }

  ngOnInit(): void {
    setTimeout(() => {
      window.scroll({
				top: 0,
				left: 0,
				behavior: 'smooth'
			});
    }, 500);
    this.addBreadcrumbSchema();
  }

  addBreadcrumbSchema() {
  const existingScript = document.getElementById('breadcrumb-schema-process');
  if (existingScript) return;

  const script = document.createElement('script');
  script.type = 'application/ld+json';
  script.id = 'breadcrumb-schema-process';

  script.text = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      {
        "@type": "ListItem",
        "position": 1,
        "name": "Home",
        "item": "https://www.pixtar.ae/"
      },
      {
        "@type": "ListItem",
        "position": 2,
        "name": "Process",
        "item": "https://www.pixtar.ae/process"
      }
    ]
  });

  document.head.appendChild(script);
}
  get_PageMeta() {
    let obj = { pageName: 'process' };
    this.pageservice.getpageWithName(obj).subscribe(
        (response) => {
            if (response.body.code == 200) {
              if(response.body.result){
                this.titleService.setTitle(response?.body.result.meta_title);
                // this.metaTagService.addTags([
                //     { name: 'description', content: response?.body.result.meta_description },
                //     { name: 'keywords', content: response?.body.result.meta_keywords },
                // ]);
                this.metaTagService.updateTag({ name: 'description', content: response?.body.result.meta_description });
					      this.metaTagService.updateTag({ name: 'keywords', content: response?.body.result.meta_keywords });
                this.metaTagService.updateTag({ rel: 'canonical', href: 'https://www.pixtar.ae/process' });
              }
            } else if (response.body.code == 400) {
            }
            else {

            }

        },
    );
}
}
