addBreadcrumbSchema() {
  const existingScript = document.getElementById('breadcrumb-schema-studio');
  if (existingScript) return;

  const script = document.createElement('script');
  script.type = 'application/ld+json';
  script.id = 'breadcrumb-schema-studio';

  script.text = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      {
        "@type": "ListItem",
        "position": 1,
        "name": "Home",
        "item": "https://www.pixtar.ae/"
      },
      {
        "@type": "ListItem",
        "position": 2,
        "name": "Studio",
        "item": "https://www.pixtar.ae/studio"
      }
    ]
  });

  document.head.appendChild(script);
}
