import { Component, Input, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { OwlOptions } from 'ngx-owl-carousel-o';
import { TestimonialService } from 'src/app/providers/testimonial/testimonial.service';
import { environment } from 'src/environments/environment';
import { Carousel } from 'bootstrap';
@Component({
	selector: 'app-testimonial',
	templateUrl: './testimonial.component.html',
	styleUrls: ['./testimonial.component.scss']
})
export class TestimonialComponent implements OnInit {

	isExpanded: boolean = false;
	baseUrl: any;
	imagepath: any;
	testimonials: any = [];
	@Input() isWhiteText: boolean = true;
	@ViewChild('myCarousel', { static: false }) carouselRef!: ElementRef;
	@Input() bannerClass: string = 'bannerdrk';

	desktopslider: OwlOptions = {
		items: 1,
		margin: 10,
		loop: true,
		rewind: true,
		autoplay: true,
		autoplayTimeout: 3000,
		autoplayHoverPause: true,
		center: true,
		dots: true,
		autoHeight: false,
		autoWidth: true,
		smartSpeed: 800,
	};



	private isDown = false;
	private startX = 0;

	ngOnInit(): void {
		this.getTestimonial();
	}

	// ngAfterViewInit(): void {
	// 	const carouselEl = this.carouselRef.nativeElement;

	// 	// Initialize Bootstrap Carousel
	// 	const carouselInstance = new Carousel(carouselEl, {
	// 		interval: 4000,
	// 		touch: true,      // Enables swipe on touch devices
	// 		wrap: true,
	// 		keyboard: true
	// 	});

	// 	// Optional: Pause on hover
	// 	carouselEl.addEventListener('mouseenter', () => carouselInstance.pause());
	// 	carouselEl.addEventListener('mouseleave', () => carouselInstance.cycle());
	// }
	constructor(
		private testimonialService: TestimonialService,
	) {
		this.imagepath = environment.backendUrl + '/public/';
	}

	getTestimonial() {
		const obj = {};
		this.testimonialService.getTestimonialData(obj).subscribe(
			(response) => {
				if (response.code === 200 && response.testimonialData?.length > 0) {
					this.testimonials = response.testimonialData.sort((a: any, b: any) => a.sequence - b.sequence);
					// console.log(this.testimonials);

				} else {
					this.testimonials = []; // Fallback to an empty array if no testimonials found
				}
			},
			(error) => {
				console.error('Failed to fetch testimonial data', error);
				this.testimonials = []; // Error case fallback
			}
		);
	}


	// Toggle expand/collapse for a specific testimonial
	toggleText(testimonial: any) {
		testimonial.isExpanded = !testimonial.isExpanded;
	}

}
