import { Component, OnInit, OnDestroy, ElementRef, HostListener, Inject, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser, Location } from '@angular/common';
import { Router } from '@angular/router';
import { environment } from '../../../environments/environment';
@Component({
	selector: 'app-navbar',
	templateUrl: './navbar.component.html',
	styleUrls: ['./navbar.component.scss']
})
export class NavbarComponent implements OnInit, OnDestroy {
	private toggleButton: any;
	private sidebarVisible: boolean;
	isNavbar: boolean = false;
	ifwhitebar: boolean = false;
	ifblackbar: boolean = true;
	baseUrl: any;
	imagepath: any;
	isMenuActive: boolean = false;
	ifbarcliked: boolean = false;
	isbarcliked: boolean = false;
	currentUrl: any;
	private readonly isBrowser: boolean;
	private navMenuListener?: (event: MouseEvent) => void;
	constructor(
		public location: Location,
		private element: ElementRef,
		public route: Router,
		@Inject(PLATFORM_ID) platformId: object,
		@Inject(DOCUMENT) private document: Document,
	) {
		this.sidebarVisible = false;
		this.imagepath = environment.baseUrl + '/public/';
		this.baseUrl = environment.baseUrl + '/assets';
		this.isBrowser = isPlatformBrowser(platformId);
	}

	private queryAll<T extends Element = HTMLElement>(selector: string): T[] {
		if (!this.isBrowser) {
			return [];
		}

		return Array.from(this.document.querySelectorAll<T>(selector));
	}

	private addClass(selector: string, className: string): void {
		this.queryAll(selector).forEach((el) => el.classList.add(className));
	}

	private removeClass(selector: string, className: string): void {
		this.queryAll(selector).forEach((el) => el.classList.remove(className));
	}

	private toggleClass(selector: string, className: string): void {
		this.queryAll(selector).forEach((el) => el.classList.toggle(className));
	}

	private updateImages(selector: string, src: string): void {
		this.queryAll<HTMLImageElement>(selector).forEach((img) => (img.src = src));
	}
	@HostListener('window:scroll', ['$event'])
	scrollHandler(event) {
		if (!this.isBrowser) {
			return;
		}

		var _location = this.location.path();
		// _location = _location.split('/')[1];
		// console.log(_location);
		if ((_location.includes('process') || _location.includes('services')) && window.scrollY > 50) {
			if (this.isbarcliked) {
				this.ifblackbar = false;
				this.ifwhitebar = true;
				this.addClass('.navbar', 'noblack');
			} else {
				this.ifblackbar = true;
				this.ifwhitebar = false;
				this.removeClass('.navbar', 'noblack');
			}
		} else if ((_location.includes('process') || _location.includes('services')) && window.scrollY < 50) {
			this.ifblackbar = false;
			this.ifwhitebar = true;
			this.addClass('.navbar', 'noblack');
		}
	}
	ngOnInit() {
		// Subscribe to router events
		this.loadInitalData();

	}

	ngOnDestroy(): void {
		if (!this.isBrowser) {
			return;
		}

		const navMenus = this.document.getElementById('navMenus');
		if (navMenus && this.navMenuListener) {
			navMenus.removeEventListener('click', this.navMenuListener);
		}
	}

	loadInitalData() {
		const navbar: HTMLElement = this.element.nativeElement;
		// this.isMenuActive = false;
		// this.toggleButton = navbar.getElementsByClassName('navbar-toggler')[0];
		this.ifblackbar = false;
		this.attachNavMenuListener();
		this.isHomemenu();
		this.showBlackbars();
		var _location = this.location.path();
		// _location = _location.split('/')[1];
		if ((_location.includes('process') || _location.includes('services')) && !this.ifbarcliked) {
			this.ifblackbar = false;
			this.ifwhitebar = true;
			this.addClass('.navbar', 'noblack');
		}
	}

	private attachNavMenuListener(): void {
		if (!this.isBrowser) {
			return;
		}

		const navMenus = this.document.getElementById('navMenus');
		if (!navMenus) {
			return;
		}
		this.navMenuListener = (event: MouseEvent) => {
			const target = (event.target as HTMLElement)?.closest('li');
			if (!target || !navMenus.contains(target)) {
				return;
			}
			navMenus.querySelectorAll('.menu-nav-item').forEach((li) => li.classList.remove('active'));
			target.classList.add('active');
		};
		navMenus.addEventListener('click', this.navMenuListener);
	}
	sidebarOpen() {
		if (!this.isBrowser) {
			return;
		}

		const toggleButton = this.toggleButton;
		const html = this.document.getElementsByTagName('html')[0];
		// console.log(html);
		// console.log(toggleButton, 'toggle');

		setTimeout(function () {
			toggleButton.classList.add('toggled');
		}, 500);
		html.classList.add('nav-open');

		this.sidebarVisible = true;
	};
	sidebarClose() {
		if (!this.isBrowser) {
			return;
		}

		const html = this.document.getElementsByTagName('html')[0];
		// console.log(html);
		// this.toggleButton.classList.remove('toggled');
		this.sidebarVisible = false;
		html.classList.remove('nav-open');
	};
	sidebarToggle() {
		// const toggleButton = this.toggleButton;
		// const body = document.getElementsByTagName('body')[0];
		if (this.sidebarVisible === false) {
			this.sidebarOpen();
		} else {
			this.sidebarClose();
		}
	};
	isHome() {
		var titlee = this.location.prepareExternalUrl(this.location.path());
		if (titlee.charAt(0) === '#') {
			titlee = titlee.slice(1);
		}
		if (titlee === '/home') {
			return true;
		}
		else {
			return false;
		}
	}
	isDocumentation() {
		var titlee = this.location.prepareExternalUrl(this.location.path());
		if (titlee.charAt(0) === '#') {
			titlee = titlee.slice(1);
		}
		if (titlee === '/documentation') {
			return true;
		}
		else {
			return false;
		}
	}

	selectLink(data: any) {
		if (data == 'process') {
			this.ifbarcliked = false;
		}
		const burgerToggle = this.isBrowser
			? this.document.getElementById('burger-toggle') as HTMLInputElement | null
			: null;
		if (burgerToggle) {
			burgerToggle.checked = false;
		}
		this.removeClass('.showcls', 'active');
		this.removeClass('.showcls2', 'active');
	}

	showBlackbars() {
		let _location = this.location.path().split('/'); // Split URL into segments
		let firstSegment = _location[1] || ''; // Get the first segment

		if ((firstSegment === 'services' || firstSegment === 'process') && _location.length === 2 && !this.ifbarcliked) {
			this.ifblackbar = false;
			this.ifwhitebar = true;
			this.addClass('.navbar', 'noblack');
		} else {
			this.ifblackbar = true;
			this.ifwhitebar = false;
			this.removeClass('.navbar', 'noblack');
		}

		return true;
	}





	onclicchange() {
		var _location = this.location.path();
		// _location = _location.split('/')[1];
		if ((_location.includes('process') || _location.includes('services')) && !this.ifbarcliked) {
			this.ifbarcliked = true;
		} else {
			this.ifbarcliked = false;
		}
	}
	func() {
		this.updateImages('.home-icon', this.baseUrl + '/img/home/homehover.png');
	}
	func2() {
		this.updateImages('.home-icon', this.baseUrl + '/img/home/home.png');
	}
	func3() {
		this.updateImages('.home-icon', this.baseUrl + '/img/home/homewhite.png');
	}

	func4() {
		this.updateImages('.menuhome', this.baseUrl + '/img/home/homehover.png');
	}
	func5() {
		this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
	}
	func6() {
		this.updateImages('.menuhome', this.baseUrl + '/img/home/homewhite.png');
	}
	// arrwhoverfunc(){
	//   $(".arrowimg").attr("src", this.baseUrl + "/img/home/contactarrow-black.svg");

	// }
	// arrwmouseleavefunc(){
	//     $(".arrowimg").attr("src", this.baseUrl + "/img/home/contactarrow.svg");

	// }
	isHomemenu() {
		if (!this.isBrowser) {
			return;
		}

		['home', 'projects', 'about', 'process', 'contact', 'ecommerce', 'graphics', 'services', 'studio', 'website', 'branding'].forEach((id) => {
			this.document.getElementById(id)?.classList.remove('active');
		});
		let currectUrl = this.baseUrl
		var _location = this.location.path();
		// _location = _location.split('/')[1];
		if (_location == 'home' || _location == '#') {
			this.document.getElementById('home')?.classList.add('active');
			this.updateImages('.menuhome', currectUrl + '/img/home/homehover.png');
		}

		else if (_location.includes('projects')) {
			this.document.getElementById('projects')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('about')) {
			this.document.getElementById('about')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('process')) {
			this.document.getElementById('process')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/homewhite.png');
		}

		else if (_location.includes('studio')) {
			this.document.getElementById('studio')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}


		else if (_location.includes('contact')) {
			this.document.getElementById('contact')?.classList.add('active');
			// $(".arrowimg").attr("src", currectUrl + "/img/home/contactarrow-black.svg");
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}
		else if (_location.includes('services/branding')) {
			this.document.getElementById('branding')?.classList.add('active');
			// $(".arrowimg").attr("src", currectUrl + "/img/home/contactarrow-black.svg");
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('services/graphics')) {
			this.document.getElementById('graphics')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('services/ecommerce-web-development')) {
			this.document.getElementById('ecommerce')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('services/website-development')) {
			this.document.getElementById('website')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

		else if (_location.includes('services')) {
			this.document.getElementById('services')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}

	}
	labelchange() {
		// $('.showcls').css({"display":"block","position":"relative", "pz-indexosition":"1"});
		this.toggleClass('.showcls', 'active');
		this.toggleClass('.showcls2', 'active');
		if (this.isbarcliked) {
			this.isbarcliked = false;
		} else {
			this.isbarcliked = true;
			this.ifblackbar = false;
			this.ifwhitebar = true;
			this.addClass('.navbar', 'noblack');
		}
	}
}
